<?php require_once '../config.php';require_admin();if(isset($_GET['del'])){db()->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_GET['del']]);header('Location: products.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$img=upload_image('image','uploads');$vals=[$_POST['code'],$_POST['name'],slug($_POST['name']),($_POST['collection_id']?:null),$_POST['description'],$_POST['size'],(int)$_POST['stock'],$_POST['price'],$_POST['type'],isset($_POST['visible'])?1:0,isset($_POST['featured'])?1:0];if($id){$sql='UPDATE products SET code=?,name=?,slug=?,collection_id=?,description=?,size=?,stock=?,price=?,type=?,visible=?,featured=?'.($img?',image=?':'').' WHERE id=?';if($img)$vals[]=$img;$vals[]=$id;db()->prepare($sql)->execute($vals);}else{array_splice($vals,8,0,[$img]);db()->prepare('INSERT INTO products(code,name,slug,collection_id,description,size,stock,price,image,type,visible,featured) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute($vals);}header('Location: products.php');exit;}$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM products WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$cols=db()->query('SELECT * FROM collections ORDER BY sort_order,id')->fetchAll();$rows=db()->query('SELECT p.*,c.name cname FROM products p LEFT JOIN collections c ON c.id=p.collection_id ORDER BY p.id DESC')->fetchAll();?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="../assets/style.css"></head><body><div class="adminwrap"><a href="dashboard.php">← Dashboard</a><h1>Ürünler</h1><form class="admin" method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><input name="code" placeholder="Ürün kodu" value="<?=e($edit['code']??'')?>"><input name="name" required placeholder="Ürün adı" value="<?=e($edit['name']??'')?>"><select name="collection_id"><option value="">Koleksiyon seç</option><?php foreach($cols as $c):?><option value="<?=$c['id']?>" <?=isset($edit)&&$edit['collection_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><textarea name="description" placeholder="Ürün açıklaması"><?=e($edit['description']??'')?></textarea><input name="size" placeholder="Ölçü" value="<?=e($edit['size']??'')?>"><input type="number" name="stock" placeholder="Stok" value="<?=e($edit['stock']??0)?>"><input name="price" placeholder="Fiyat / Teklif" value="<?=e($edit['price']??'')?>"><select name="type"><option value="normal" <?=($edit['type']??'normal')==='normal'?'selected':''?>>Normal</option><option value="spot" <?=($edit['type']??'')==='spot'?'selected':''?>>Spot & Outlet</option></select><input type="file" name="image"><label><input type="checkbox" name="visible" <?=!isset($edit)||$edit['visible']?'checked':''?>> Yayında</label> <label><input type="checkbox" name="featured" <?=isset($edit)&&$edit['featured']?'checked':''?>> Öne çıkan</label><br><br><button class="btn">Kaydet</button></form><br><table><tr><th>Ürün</th><th>Koleksiyon</th><th>Stok</th><th>İşlem</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['cname'])?></td><td><?=e(stock_label($r['stock']))?></td><td><a href="?edit=<?=$r['id']?>">Düzenle</a> · <a href="?del=<?=$r['id']?>" onclick="return confirm('Silinsin mi?')">Sil</a></td></tr><?php endforeach;?></table></div></body></html>
